/**
 * A Button preset for copying a value to the clipboard (`design/components/copy-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/copy-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, type JSX } from 'solid-js'

import {
  Icon,
  claimSlot,
  createCell,
  createDerived,
  devWarning,
  elementRef,
  nameTip,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/copy-button.module.css'

export interface CopyButtonProps {
  /**
   * The confirmation announced to assistive technology ("Copied"). It is required, because a
   * screen reader user cannot perceive the icon change, so an announcement must exist. The
   * vocabulary writes no prose, so the app supplies both of this member's strings.
   */
  copiedLabel: string
  disabled?: boolean
  /**
   * The accessible name ("Copy install command"). No default, because naming is a decision
   * (Button's law).
   */
  label: string
  /**
   * Button's sizes without `lg`. A copy button is secondary, and at `lg` it would look like a
   * main action.
   */
  size?: 'sm' | 'md'
  /**
   * Written to the clipboard exactly as given, including whitespace.
   */
  value: string
}

/** A Button preset for copying a value to the clipboard. */
export default function CopyButton(given: CopyButtonProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false } as Defaults<CopyButtonProps, 'size' | 'disabled'>,
    claimSlot(given),
  )
  return scope(() => {
    const control = elementRef<HTMLElement>()
    const copied = createCell(false)
    const copies = createCell(0)
    const copy = createDerived(
      () => () =>
        void navigator.clipboard.writeText(props.value).then(
          () => {
            copied.value = true
            copies.value += 1
          },
          (refusal: unknown) =>
            devWarning(true, `CopyButton could not write to the clipboard: ${String(refusal)}`),
        ),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const timer = setTimeout(() => {
        copied.value = false
      }, 2000)
      release1 = () => clearTimeout(timer)
    }
    watchEffect(
      createMemo(() => copies.value),
      effect1,
      false,
    )
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = nameTip(
        control.value,
        props.disabled || copied.value ? undefined : props.label,
        styles.tip,
      )
      release2 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => [props.disabled, copied.value, props.label]),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    return (
      <>
        <button
          class={styles.button}
          type="button"
          disabled={props.disabled}
          aria-label={props.label}
          data-variant="ghost"
          data-tone="neutral"
          data-size={props.size}
          data-disabled={props.disabled ? '' : undefined}
          data-icon-only={''}
          data-state={copied.value ? 'copied' : undefined}
          data-member="copy-button"
          onclick={() => copy.value()}
          ref={control.attach}
        >
          <span class={styles.glyphs} aria-hidden="true">
            <span class={styles.copyGlyph}>
              <Icon name="copy" size={props.size} />
            </span>
            <span class={styles.confirmGlyph}>
              <Icon name="confirm" size={props.size} />
            </span>
          </span>
        </button>
        <span class={styles.status} role="status">
          {copied.value ? props.copiedLabel : ''}
        </span>
      </>
    )
  })
}
